const items = $input.all();
const dia = $("NFC Scan Webhook").first().json.query.dia;

const FONTS = `<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@500;600&display=swap" rel="stylesheet">`;

const BASE_STYLE = `
  :root {
    --bg:#0a0c0f; --bg-glow:#0f1720; --surface:#14171c; --surface-2:#1b1f25;
    --border:#262b32; --text:#f2f4f6; --text-muted:#838c98;
    --accent:#35d68a; --accent-dim:rgba(53,214,138,.12);
    --rest:#6c8cff; --rest-dim:rgba(108,140,255,.12); --radius:16px;
  }
  * { box-sizing: border-box; }
  body { background: radial-gradient(circle at 50% 0%, var(--bg-glow) 0%, var(--bg) 55%); color: var(--text); font-family:'Inter',sans-serif; margin:0; min-height:100vh; padding:40px 18px 70px 18px; }
  @keyframes rise { from { opacity:0; transform: translateY(14px);} to { opacity:1; transform: translateY(0);} }
  @media (prefers-reduced-motion: reduce) { *, *::before { animation: none !important; } }
`;

// ============ CASO 1: Día de descanso ============
if (items.length === 0) {
  let htmlDescanso = `
  <!DOCTYPE html>
  <html lang="es">
  <head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Día Libre</title>
    ${FONTS}
    <style>
      ${BASE_STYLE}
      .rest-scene { max-width: 380px; margin: 60px auto 0 auto; text-align: center; animation: rise .6s cubic-bezier(.2,.8,.2,1) both; }
      .rest-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 40px 28px; box-shadow: 0 20px 60px rgba(0,0,0,.45); }
      .rest-icon { width: 46px; height: 46px; margin: 0 auto 20px auto; border-radius: 50%; background: var(--rest-dim); border: 1.5px solid var(--rest); display:flex; align-items:center; justify-content:center; }
      .rest-icon svg { width: 20px; height: 20px; stroke: var(--rest); }
      .rest-card h1 { font-family:'Space Grotesk',sans-serif; font-size: 1.4rem; margin: 0 0 8px 0; }
      .rest-card p { color: var(--text-muted); font-size: .95rem; line-height: 1.55; margin: 0; }
    </style>
  </head>
  <body>
    <div class="rest-scene">
      <div class="rest-card">
        <div class="rest-icon">
          <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>
        </div>
        <h1>Día de descanso</h1>
        <p>No tenés ejercicios asignados para este ${dia}.<br>Aprovechá para recuperarte bien.</p>
      </div>
    </div>
  </body>
  </html>`;
  return [{ json: { html_final: htmlDescanso } }];
}

// ============ CASO 2: Hay rutina ============
let nombreAlumno = items[0].json.nombre_alumno;

let tarjetasEjercicios = items.map((item, i) => {
  let ej = item.json;
  return `
  <div class="exercise" data-orden="${ej.orden}" style="animation-delay:${i * 0.07}s">
    <h3>${ej.nombre_ejercicio}</h3>
    <div class="stats">
      <div class="stat"><span class="label">Series</span><span class="value">${ej.series}</span></div>
      <div class="stat"><span class="label">Reps</span><span class="value">${ej.repeticiones}</span></div>
    </div>
    <span class="rest-pill">
      <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg>
      Descanso ${ej.descanso} seg
    </span>
  </div>`;
}).join("");

let htmlCompleto = `
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Rutina | ${dia}</title>
  ${FONTS}
  <style>
    ${BASE_STYLE}
    .container { max-width: 460px; margin: 0 auto; }
    header { text-align: center; margin-bottom: 32px; animation: rise .6s cubic-bezier(.2,.8,.2,1) both; }
    .eyebrow { display:inline-flex; align-items:center; gap:8px; font-family:'JetBrains Mono',monospace; font-size:.68rem; letter-spacing:.14em; text-transform:uppercase; color:var(--text-muted); margin-bottom:14px; }
    .eyebrow .dot { width:6px; height:6px; border-radius:50%; background:var(--accent); box-shadow:0 0 0 3px var(--accent-dim); }
    h1 { font-family:'Space Grotesk',sans-serif; font-size:1.7rem; font-weight:700; letter-spacing:-.01em; margin:0 0 4px 0; }
    h1 span { color: var(--accent); }
    .subtitle { font-size:.95rem; color:var(--text-muted); margin:0; }
    .timeline { position: relative; padding-left: 34px; }
    .timeline::before { content:""; position:absolute; left:11px; top:6px; bottom:6px; width:2px; background: linear-gradient(180deg, var(--accent) 0%, var(--border) 100%); opacity:.5; }
    .exercise { position:relative; background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:18px 18px 16px 18px; margin-bottom:14px; animation: rise .5s cubic-bezier(.2,.8,.2,1) both; }
    .exercise::before { content: attr(data-orden); position:absolute; left:-34px; top:18px; width:24px; height:24px; border-radius:50%; background:var(--bg); border:2px solid var(--accent); color:var(--accent); font-family:'JetBrains Mono',monospace; font-size:.7rem; font-weight:600; display:flex; align-items:center; justify-content:center; }
    .exercise h3 { font-family:'Space Grotesk',sans-serif; font-size:1.05rem; font-weight:600; margin:0 0 12px 0; letter-spacing:-.005em; }
    .stats { display:flex; gap:10px; margin-bottom:10px; }
    .stat { flex:1; background:var(--surface-2); border:1px solid var(--border); border-radius:10px; padding:9px 10px; text-align:center; }
    .stat .label { display:block; font-family:'JetBrains Mono',monospace; font-size:.6rem; letter-spacing:.08em; text-transform:uppercase; color:var(--text-muted); margin-bottom:3px; }
    .stat .value { font-family:'JetBrains Mono',monospace; font-size:1.05rem; font-weight:600; color:var(--text); }
    .rest-pill { display:inline-flex; align-items:center; gap:6px; font-size:.78rem; color:var(--text-muted); background:var(--surface-2); border:1px solid var(--border); border-radius:20px; padding:5px 12px; }
    .rest-pill svg { width:12px; height:12px; stroke:var(--text-muted); }
    footer { text-align:center; margin-top:30px; font-size:.78rem; color:#4a515c; }
  </style>
</head>
<body>
  <div class="container">
    <header>
      <div class="eyebrow"><span class="dot"></span>${dia} · Sesión de hoy</div>
      <h1>A darle, <span>${nombreAlumno}</span></h1>
      <p class="subtitle">${items.length} ejercicios programados para esta sesión</p>
    </header>
    <div class="timeline">
      ${tarjetasEjercicios}
    </div>
    <footer>Sesión generada automáticamente para hoy</footer>
  </div>
</body>
</html>
`;

return [{ json: { html_final: htmlCompleto } }];

